import { IMMessage, DeleteSelfMsgsOptions, DeleteSelfMsgsResult, ResendMsgOptions, RecallMsgOptions, SendMsgReceiptOptions, SendTeamMsgReceiptOptions, GetTeamMsgReadsOptions, GetTeamMsgReadsResult, ForwardMsgOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/MsgServiceInterface';
import { ClearHistoryMsgsFromServerOptions, GetHistoryMsgsOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/MsgLogServiceInterface';
import { ISendTextMsgOptions, IBaseSendFileOptions, ISendCustomMsgOptions, IUploadFileOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/types';
import { AddFriendOptions, ApplyFriendOptions, DeleteFriendOptions, FriendProfile, PassFriendApplyOptions, RejectFriendApplyOptions, UpdateFriendOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/FriendServiceInterface';
import { Session, NIM_AddStickTopSessionOptions, NIM_DeleteStickTopSessionOptions, SessionIdOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/SessionServiceInterface';
import { TeamMember, Team, CreateTeamOptions, ApplyTeamOptions, UpdateTeamInfoOptions, RemoveTeamMembersOptions, MuteTeamOptions, AddTeamMembersOptions, GetTeamMembersOptions, RejectTeamInviteOptions, AcceptTeamInviteOptions, RejectTeamApplyOptions, PassTeamApplyOptions, TransferTeamOptions, RemmoveTeamManagersOptions, AddTeamManagersOptions, UpdateMyMemberInfoOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/TeamServiceInterface';
import { GetUsersNameCardFromServerOptions, UpdateMyInfoOptions, UpdateRelationsOptions, UserNameCard } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/UserServiceInterface';
import { IMEventInterface, NIMInitializeOptions, NIMOtherOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/NIMInterface';
import { ArgumentMap } from 'eventemitter3';
import { GetMsgsByIdServerOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/MsgExtendServiceInterface';
import { SubscribeEventOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/EventServiceInterface';
export type IFriendInfo = FriendProfile & UserNameCard;
export type P2PSession = Session & {
    isMute: boolean;
};
export type TeamSession = Session & Team;
export type ISession = P2PSession | TeamSession;
export type ConnectState = 'connecting' | 'connected' | 'disconnected' | 'idle';
export interface INimKitCore {
    version: string;
    platform: string;
    connectState: ConnectState;
    initOptions: NIMInitializeOptions;
    otherOptions: NIMOtherOptions;
    saveMyUserInfo(params: IUploadFileOptions & UpdateMyInfoOptions): Promise<UserNameCard>;
    isSessionExist(sessionId: string): Promise<boolean>;
    resetSessionUnreadCount(options: SessionIdOptions): Promise<void>;
    addFriend(options: AddFriendOptions): Promise<FriendProfile>;
    applyFriend(options: ApplyFriendOptions): Promise<void>;
    deleteFriend(options: DeleteFriendOptions): Promise<void>;
    updateFriend(options: UpdateFriendOptions): Promise<void>;
    setBlack(options: UpdateRelationsOptions): Promise<void>;
    deleteSession(options: {
        id: string;
        isSyncToServer: boolean;
    }): Promise<void>;
    setMute(options: UpdateRelationsOptions): Promise<void>;
    passFriendApply(options: PassFriendApplyOptions): Promise<void>;
    rejectFriendApply(options: RejectFriendApplyOptions): Promise<void>;
    passTeamApply(options: PassTeamApplyOptions): Promise<void>;
    rejectTeamApply(options: RejectTeamApplyOptions): Promise<void>;
    acceptTeamInvite(options: AcceptTeamInviteOptions): Promise<void>;
    rejectTeamInvite(options: RejectTeamInviteOptions): Promise<void>;
    addStickTopSession(options: NIM_AddStickTopSessionOptions): Promise<Session>;
    deleteStickTopSession(options: NIM_DeleteStickTopSessionOptions): Promise<Session>;
    forwardMsg(options: ForwardMsgOptions): Promise<IMMessage>;
    subscribeEvent(options: SubscribeEventOptions): Promise<void>;
    addTeamManagers(options: AddTeamManagersOptions): Promise<void>;
    removeTeamManagers(options: RemmoveTeamManagersOptions): Promise<void>;
    connect(): Promise<void>;
    disconnect(): Promise<void>;
    destroy(): Promise<void>;
    getNIM(): any;
    createTeam(options: CreateTeamOptions): Promise<Team>;
    addTeamMembers(options: AddTeamMembersOptions): Promise<void>;
    getUsersNameCardFromServer(options: GetUsersNameCardFromServerOptions): Promise<UserNameCard[]>;
    getTeamInfo(options: {
        teamId: string;
    }): Promise<Team>;
    applyTeam(options: ApplyTeamOptions): Promise<Team>;
    removeTeamMembers(options: RemoveTeamMembersOptions): Promise<void>;
    getTeamMembers(params: GetTeamMembersOptions): Promise<TeamMember[]>;
    updateTeamInfo(options: UpdateTeamInfoOptions): Promise<Partial<Team>>;
    updateMyMemberInfo(options: UpdateMyMemberInfoOptions): Promise<TeamMember>;
    muteTeam(options: MuteTeamOptions): Promise<void>;
    dismissTeam(options: {
        teamId: string;
    }): Promise<void>;
    transferTeam(options: TransferTeamOptions): Promise<void>;
    leaveTeam(options: {
        teamId: string;
    }): Promise<void>;
    getMsgsByIdServer(params: GetMsgsByIdServerOptions): Promise<IMMessage[]>;
    sendTextMsg(options: ISendTextMsgOptions): Promise<IMMessage>;
    sendImageMsg(options: IBaseSendFileOptions): Promise<IMMessage>;
    sendFileMsg(options: IBaseSendFileOptions): Promise<IMMessage>;
    sendCustomMsg(options: ISendCustomMsgOptions): Promise<IMMessage>;
    sendVideoMsg(options: IBaseSendFileOptions): Promise<IMMessage>;
    sendAudioMsg(options: IBaseSendFileOptions): Promise<IMMessage>;
    clearHistoryMsgsFromServer(options: ClearHistoryMsgsFromServerOptions): Promise<void>;
    getTeamMsgReads(options: GetTeamMsgReadsOptions): Promise<GetTeamMsgReadsResult>;
    deleteSelfMsgs(options: DeleteSelfMsgsOptions): Promise<DeleteSelfMsgsResult[]>;
    getHistoryMsgs(options: GetHistoryMsgsOptions): Promise<IMMessage[]>;
    resendMsg(options: ResendMsgOptions): Promise<IMMessage>;
    recallMsg(options: RecallMsgOptions): Promise<IMMessage>;
    sendMsgReceipt(options: SendMsgReceiptOptions): Promise<void>;
    sendTeamMsgReceipt(options: SendTeamMsgReceiptOptions): Promise<void>;
    on<T extends keyof IMEventInterface>(eventName: T, fn: (...args: ArgumentMap<IMEventInterface>[Extract<T, keyof IMEventInterface>]) => void, context?: any): this;
    off<T extends keyof IMEventInterface>(eventName: T, fn?: ((...args: ArgumentMap<IMEventInterface>[Extract<T, keyof IMEventInterface>]) => void) | undefined, context?: any, once?: boolean | undefined): this;
    emit<T extends keyof IMEventInterface>(event: T, ...args: ArgumentMap<IMEventInterface>[Extract<T, keyof IMEventInterface>]): boolean;
}
